const GLOSSARY = [
  {
    "term": "Agent",
    "says": "An autonomous AI that thinks and acts on its own",
    "means": "A loop that calls an LLM, lets it pick a tool, executes that tool, feeds the result back, and repeats until done. The architecture under every \"AI assistant\" your client is buying. Cost and reliability are driven by loop length, tool-call count, and error handling between steps."
  },
  {
    "term": "Attention",
    "says": "How the AI focuses on important parts",
    "means": "The mechanism that lets an LLM decide which prior tokens matter for the next one. Context window exists because attention's compute cost is quadratic in sequence length. Pricing, latency, and the cache-pricing math all derive from this."
  },
  {
    "term": "Alignment",
    "says": "Making AI safe",
    "means": "How well the model's behavior matches the client's intent, including edge cases the prompt didn't anticipate. A client will say \"the AI sounds rude\" or \"it gave a wrong answer\" — that's an alignment problem, not a model-quality problem."
  },
  {
    "term": "Autoregressive",
    "says": "The AI generates one word at a time",
    "means": "The model generates output one token at a time, each conditioned on all previous tokens. This is why latency is dominated by output length — TTFT is fast, total time scales with tokens out. All current frontier chat models are autoregressive."
  },
  {
    "term": "AI Gateway",
    "says": "A proxy in front of LLMs",
    "means": "A proxy that sits between your app and one or more LLM providers. It centralizes auth, routing, retries, logging, cost attribution, and rate limiting. When the client asks \"how do we govern model use across teams?\" — the answer is a gateway."
  },
  {
    "term": "Context Window",
    "says": "How much the AI can remember",
    "means": "The max tokens (input + output) the model accepts in a single call. **This is not memory.** Each call starts fresh. Anything outside the window is invisible to the model."
  },
  {
    "term": "Chain of Thought (CoT)",
    "says": "Making the AI think step by step",
    "means": "Telling the model to \"think step by step\" before answering. It works because intermediate tokens condition the next-token prediction. Costs more (more output tokens) but buys accuracy on multi-step reasoning."
  },
  {
    "term": "Chunking",
    "says": "Splitting documents into pieces",
    "means": "Splitting documents into pieces before embedding for RAG. Chunk size is the single biggest lever on retrieval quality."
  },
  {
    "term": "Cosine Similarity",
    "says": "How similar two vectors are",
    "means": "The standard similarity metric between two embedding vectors. Range -1 to 1; in practice RAG results cluster between 0.5 and 0.95. The \"how close is close enough?\" threshold differs per embedding model — never borrow thresholds across models."
  },
  {
    "term": "CUDA",
    "says": "GPU programming",
    "means": "NVIDIA's GPU compute platform. A TC rarely touches CUDA directly but pays for GPU hours on hosted inference (AWS, Azure, Modal, Replicate). Pricing models are GPU-hour based."
  },
  {
    "term": "Embedding",
    "says": "Some AI magic that turns words into numbers",
    "means": "A vector representation of text (or images, audio, etc.) such that similar meaning → nearby vectors. This is what powers semantic search, RAG retrieval, recommendations, and clustering."
  },
  {
    "term": "Eval Harness",
    "says": "Tests for AI outputs",
    "means": "The test rig you build to grade model outputs. It is the document you hand a steering committee the morning the trade-off is questioned. Without one, every deployment is a hope."
  },
  {
    "term": "Few-Shot",
    "says": "Give the AI some examples first",
    "means": "Putting 3-5 examples in the prompt to show the model the format and behavior you want. Cheaper than fine-tuning, re-deployable in seconds."
  },
  {
    "term": "Fine-Tuning",
    "says": "Training the AI on your data",
    "means": "Continuing training of a pre-trained model on your smaller, task-specific dataset. It changes model weights, not just prompts. Costs GPU hours + labeling time."
  },
  {
    "term": "Function Calling (Tool Use)",
    "says": "AI that can use tools",
    "means": "A structured protocol where the LLM outputs a JSON object naming a tool and its arguments; your code executes the tool; the result returns to the model. This is the **mechanism**; agents are the **loop**."
  },
  {
    "term": "Guardrails",
    "says": "Safety filters for AI",
    "means": "Input/output filters around the LLM that detect prompt injection, PII leakage, off-topic responses, or unsafe outputs. A TC's job is to ship an LLM app into a regulated tenant without being the person who gets fired when something goes wrong."
  },
  {
    "term": "GPT",
    "says": "ChatGPT\" or \"The AI",
    "means": "OpenAI's family of decoder-only transformer models. Specific model names change quarterly — verify on the provider's pricing page before any client deliverable."
  },
  {
    "term": "Generative AI",
    "says": "AI that creates things",
    "means": "AI that produces novel outputs (text, images, code, audio) rather than classifying or scoring. Every client engagement you're on is in this bucket."
  },
  {
    "term": "Graph Engineering",
    "says": "A fancier workflow diagram",
    "means": "Making an agent system's nodes, edges, shared state, and routing rules explicit so branches, rollback, checkpoints, and approval boundaries can be tested and replayed. A graph may contain deterministic jobs, tools, human gates, and full agent loops."
  },
  {
    "term": "Harness Engineering",
    "says": "A better prompt for the coding agent",
    "means": "Designing the repository environment around an agent so instructions, durable state, scope, runtime feedback, verification, review, and handoff make delivery repeatable across sessions."
  },
  {
    "term": "Hallucination",
    "says": "The AI is lying\" or \"making things up",
    "means": "The model produces plausible text that isn't grounded in the input or its training data. It is **not a bug to fix** — it is a property of how LLMs work. The job is to **bound** it: retrieval-grounded prompts, output validators, attribution display."
  },
  {
    "term": "Inference",
    "says": "Running the AI",
    "means": "Running a trained model on new data. No weight updates. This is what you pay the provider for: input tokens + output tokens."
  },
  {
    "term": "LLM (Large Language Model)",
    "says": "AI\" or \"the brain",
    "means": "A transformer-based model trained to predict the next token, on billions of parameters, on internet-scale text. The default building block of every AI engagement you'll see in 2026."
  },
  {
    "term": "Latency",
    "says": "How fast the AI responds",
    "means": "Two numbers that matter: **TTFT** (time to first token — perceived \"snappiness\") and **end-to-end** (last token out — total response time)."
  },
  {
    "term": "Loop Engineering",
    "says": "Let the agent run by itself",
    "means": "Designing the trigger, durable state, maker/evaluator boundary, feedback path, and stop policy that let an agent make bounded progress without a person prompting every turn."
  },
  {
    "term": "MCP (Model Context Protocol)",
    "says": "A way for AI to use tools",
    "means": "An open standard (JSON-RPC) for connecting LLMs to external tools and data sources. Anthropic released it November 2024; adopted across most major agent frameworks since."
  },
  {
    "term": "Multi-Modal",
    "says": "AI that handles images and audio",
    "means": "Models that accept or produce more than text (images, audio, video). Adds cost (vision tokens are expensive) and changes prompt shape. Always verify the model's modality matrix before scoping — \"it accepts images\" varies wildly (size limits, resolution limits, format support)."
  },
  {
    "term": "Output Tokens",
    "says": "What the model writes",
    "means": "What the model generates. **This is where the bill lives.** Output tokens cost 3-5x more than input tokens across major providers."
  },
  {
    "term": "Prompt Engineering",
    "says": "Talking to AI the right way",
    "means": "Designing the input text — system prompt, few-shot examples, format instructions — to produce desired outputs reliably. The cheapest performance lever you have."
  },
  {
    "term": "Prompt Injection",
    "says": "Hacking the AI with words",
    "means": "A user (or a document the user supplies) overrides the system prompt via malicious input. The LLM equivalent of SQL injection. No complete solution exists."
  },
  {
    "term": "Perplexity",
    "says": "How confused the model is",
    "means": "A training/eval metric (exp of cross-entropy loss). Not directly actionable in delivery unless you're choosing between base models on a private benchmark."
  },
  {
    "term": "Quantization",
    "says": "Making the model smaller",
    "means": "Reducing the precision of model weights (float32 → int8 or int4) to shrink memory and speed inference. Trades a small accuracy loss for 4-8x size reduction."
  },
  {
    "term": "RAG (Retrieval-Augmented Generation)",
    "says": "AI that can search",
    "means": "Retrieve relevant documents from a knowledge base → stuff them into the prompt → let the LLM answer with that context. **The default pattern for any \"ask the docs\" client engagement.**"
  },
  {
    "term": "RLHF (Reinforcement Learning from Human Feedback)",
    "says": "How they make AI helpful",
    "means": "The training pipeline that turns a base model into a chat model. Done by the vendor, not by you. The output is a model that's \"helpful\" in the vendor's definition of helpful."
  },
  {
    "term": "Reasoning Model",
    "says": "AI that thinks harder",
    "means": "Models that emit extended chain-of-thought before answering (o-series, Claude with extended thinking, Gemini Thinking). Higher cost and latency, higher accuracy on math/code/multi-step."
  },
  {
    "term": "Scope Contract",
    "says": "The files the agent should touch",
    "means": "A task-level authorization boundary listing allowed and forbidden paths plus the acceptance conditions for one feature or change."
  },
  {
    "term": "Semantic Search",
    "says": "Smart search that understands meaning",
    "means": "Finding documents by meaning, not keywords. Embed the query and all documents, return the closest. This is the retrieval half of RAG."
  },
  {
    "term": "Streaming",
    "says": "Seeing the response appear word by word",
    "means": "The provider sends tokens as the model generates them (SSE or WebSocket), instead of waiting for the full response. Reduces perceived latency from seconds to milliseconds for the first token."
  },
  {
    "term": "System Prompt",
    "says": "The AI's instructions",
    "means": "The hidden instruction block at the start of the conversation that sets the model's persona, tone, and constraints. The TC's primary lever for shaping model behavior."
  },
  {
    "term": "SFT (Supervised Fine-Tuning)",
    "says": "Teaching the model to follow instructions",
    "means": "Fine-tuning on (instruction, response) pairs. The standard way to teach a model a new task shape. Higher cost than few-shot; lower cost than RLHF."
  },
  {
    "term": "Token",
    "says": "A word",
    "means": "The unit the model reads and writes. Not a word — a subword chunk (typically 3-4 characters in English). A sentence might be 20-40 tokens. **Pricing, context window, and latency all count in tokens, not words.**"
  },
  {
    "term": "Temperature",
    "says": "Creativity setting",
    "means": "A knob on the sampling distribution. 0 = deterministic (always pick top token). 1 = default. Higher = more random."
  },
  {
    "term": "Transformer",
    "says": "The architecture behind modern AI",
    "means": "The architecture behind every modern LLM. You don't need to derive it. You need to know that **input cost scales with sequence length squared-ish (attention is quadratic)** — which is why long-context pricing is steeper than short-context."
  },
  {
    "term": "Verification Gate",
    "says": "The agent says it works",
    "means": "A deterministic or independently reviewed checkpoint that requires named acceptance checks and records pass/fail evidence before a task can advance."
  },
  {
    "term": "Vector Database",
    "says": "A special database for AI",
    "means": "A database optimized for storing vectors and finding approximate nearest neighbors. Required infrastructure for any RAG system above ~10K documents."
  },
  {
    "term": "Zero-Shot",
    "says": "No training needed",
    "means": "Asking the model to perform a task with no examples. Works because pre-training covered the pattern. Cheapest mode — use it first, escalate to few-shot only when zero-shot fails."
  }
];

